<script>(()=>{const tabs=document.getElementById('pmProjectTabs');if(!tabs)return;const groups={overview:Array.from(document.querySelectorAll('.pm-overview-section')),analytics:Array.from(document.querySelectorAll('.pm-analytics-section')),budgets:Array.from(document.querySelectorAll('.phase-budget-section')),requests:Array.from(document.querySelectorAll('.pm-requests-section'))};const show=n=>{if(!groups[n])n='overview';Object.values(groups).flat().forEach(e=>e.hidden=true);groups[n].forEach(e=>e.hidden=false);tabs.querySelectorAll('button').forEach(b=>{b.classList.toggle('btn-primary',b.dataset.projectView===n);b.classList.toggle('btn-ghost',b.dataset.projectView!==n)});history.replaceState(null,'','#'+n)};tabs.addEventListener('click',e=>{const b=e.target.closest('[data-project-view]');if(b)show(b.dataset.projectView)});const graphButton=document.getElementById('togglePmGraphs');const graphs=document.getElementById('pmGraphs');graphButton?.addEventListener('click',()=>{graphs.hidden=!graphs.hidden;graphButton.textContent=graphs.hidden?'Show Graphs':'Hide Graphs'});show(location.hash.slice(1)||'overview')})();</script>
